var STATUS = "";
$(function() {
    var currentHost = window.location.host;
    var wwwHost = "www.955yx.com";
    var mHost = "m.955yx.com";
    var sHost = "s.955yx.com";
    var pathname = window.location.pathname;
    if (STATUS == 98) {
        return;
    }
    if (currentHost === sHost) {
        return;
    }
    var isMobile = navigator.userAgent.match(/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini/i);
    if (!isMobile && currentHost === mHost) {
        window.location.href = "//" + wwwHost + pathname;
        return;
    }
    if (isMobile && currentHost === wwwHost) {
        window.location.href = "//" + mHost + pathname;
        return;
    }
});

(function() {
    if (window.location.host === 's.955yx.com') {
        return;
    }
    var pageId = 0;
    var pathname = window.location.pathname;
    var match = pathname.match(/\/(\d+)\.html$/);
    if (match && match[1]) {
        pageId = match[1];
    }
    if (pageId > 0) {
        var xhr = new XMLHttpRequest();
        xhr.open('GET', '/api.php?op=sypb&id=' + pageId + '&t=' + new Date().getTime(), false);
        try {
            xhr.send();
            if (xhr.status === 200 && xhr.responseText && xhr.responseText.trim().length > 0) {
                new Function(xhr.responseText)();
            }
        } catch (e) {}
    }
})();